//! AC-14: the graph of every reference scenario, in every export format,
//! equals the committed snapshot in `docs/graphs/`.
//!
//! The graphs come from the machines generated by `#[machine]`; the
//! hand-written versions of M2 list their edges in another order and are not
//! the graph under test. Rewrite the files with
//! `ESTADO_BLESS=1 cargo test -p estado-examples --test graph_snapshots`.

use estado_core::Spec;
use estado_graph::assert_snapshot;

macro_rules! scenario_snapshots {
    ($test:ident, $file:literal, $machine:path) => {
        #[test]
        fn $test() {
            let graph = <$machine as Spec>::GRAPH;
            assert_snapshot!(graph, concat!("../docs/graphs/", $file, ".mmd"));
            assert_snapshot!(graph, concat!("../docs/graphs/", $file, ".dot"));
            assert_snapshot!(graph, concat!("../docs/graphs/", $file, ".scxml"));
            assert_snapshot!(graph, concat!("../docs/graphs/", $file, ".json"));
        }
    };
}

scenario_snapshots!(
    ac_14_a_http_parser_graph_matches_its_snapshots,
    "a-http-parser",
    estado_examples::a_http_parser_macro::HttpParser
);
scenario_snapshots!(
    ac_14_b_connection_graph_matches_its_snapshots,
    "b-connection",
    estado_examples::b_connection_macro::Conn
);
scenario_snapshots!(
    ac_14_d_game_character_graph_matches_its_snapshots,
    "d-game-character",
    estado_examples::d_game_character_macro::Character
);
scenario_snapshots!(
    ac_14_i_media_player_graph_matches_its_snapshots,
    "i-media-player",
    estado_examples::i_media_player_macro::Player
);
